contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public payable {
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!reverted && minSumAfter == minSumBefore);
    }

    receive() external payable {}
}

